// และใหม่ที่มีน้ำหนักกรัม ("แตงกวา 10g", "กล้วย 30g", "ส้ม 20g")
function resolveVarName(v){
  v=String(v||'').trim();
  if(!v)return v;
  if(VAR_MAP[v])return VAR_MAP[v];                       // 1. ชื่อที่ map ไว้ตรงตัว
  const known=Object.keys(PRODUCT_ICONS);
  if(known.includes(v))return v;                         // 2. ตรงชื่อสินค้าอยู่แล้ว (เช่น "ข้าวโพด 6 แว่น")
  if(v.includes('ข้าวโพด')){                              // 3. ข้าวโพด: จับจำนวนแว่น
    if(/6\s*แว่น/.test(v))return 'ข้าวโพด 6 แว่น';
    if(/3\s*แว่น/.test(v))return 'ข้าวโพด 3 แว่น';
  }
  const noGram=v.replace(/\s*\d+(\.\d+)?\s*g\.?$/i,'').trim();  // 4. ตัดน้ำหนักกรัม
  if(VAR_MAP[noGram])return VAR_MAP[noGram];
  if(known.includes(noGram))return noGram;
  const noDry=noGram.replace(/\s*อบแห้ง\s*/g,' ').trim();        // 5. ตัด "อบแห้ง"
  if(VAR_MAP[noDry])return VAR_MAP[noDry];
  if(known.includes(noDry))return noDry;
  return v;                                              // fallback: ชื่อดิบ
}

